import pandas as pd, numpy as np
for i in [1,2,3,4,6,7,8]:
    try:
        df = pd.read_csv(eval(f"experiment_{i}_csv"))
        print(f"--- exp {i} ---", list(df.columns))
        print(df.describe().round(2).T[['mean','std']])
        print("corr with conversion:")
        cc = df.corr(numeric_only=True)
        conv = [c for c in df.columns if 'onversion' in c or 'Conv' in c]
        if conv:
            print(cc[conv[0]].round(3))
    except Exception as e:
        print(i, "err", e)

